changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.catalog_collections_owner_from_docs()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $fn$
DECLARE
    v_owner  text;
    v_holder text;
BEGIN
    IF NEW.content_type IN ('code', 'docs', 'rdr')
       AND nexus.catalog_collection_owner_replaceable(NEW.tenant_id, NEW.owner_id) THEN
        v_owner := nexus.catalog_collection_doc_owner(NEW.tenant_id, NEW.name);
        IF v_owner IS NOT NULL AND v_owner IS DISTINCT FROM NEW.owner_id THEN
            -- catalog-051-2: an unsuperseded, non-quarantine row must not land on a tuple another such row holds. The
            -- transaction-scoped advisory lock on the tuple makes two writers onto one free tuple take turns, so the
            -- second one's SELECT sees the first one's committed row instead of racing it into the unique index.
            -- RDR-229 P3.5b: superseded and the holder's identity are read by id (superseded_by_id, collection_id).
            IF NEW.lifecycle_state <> 'quarantine' AND NEW.superseded_by_id IS NULL THEN
                PERFORM pg_advisory_xact_lock(nexus.collection_tuple_lock_key(
                    NEW.tenant_id, NEW.content_type, v_owner, NEW.embedding_model, NEW.model_version));
            END IF;
            SELECT h.name INTO v_holder
              FROM nexus.catalog_collections h
             WHERE NEW.lifecycle_state <> 'quarantine' AND NEW.superseded_by_id IS NULL
               AND h.tenant_id = NEW.tenant_id
               AND h.content_type = NEW.content_type
               AND h.owner_id = v_owner
               AND h.embedding_model = NEW.embedding_model
               AND h.model_version = NEW.model_version
               AND h.lifecycle_state <> 'quarantine' AND h.superseded_by_id IS NULL
               AND h.collection_id IS DISTINCT FROM NEW.collection_id
             ORDER BY h.name
             LIMIT 1;
            IF FOUND THEN
                RAISE NOTICE 'catalog-051: collection % keeps owner_id % (its documents name %, which collection % already holds for this content type, model and version)',
                    NEW.name, NEW.owner_id, v_owner, v_holder;
            ELSE
                RAISE NOTICE 'catalog-044: collection % owner_id % -> % (from its documents)',
                    NEW.name, NEW.owner_id, v_owner;
                NEW.owner_id := v_owner;
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$fn$;

