changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.catalog_documents_owner_to_collection()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $fn$
DECLARE
    v_seg    text;
    v_name   text;
    v_cur    text;
    v_ct     text;
    v_em     text;
    v_mv     text;
    v_ls     text;
    v_sup    boolean;
    v_new    text;
    v_holder text;
BEGIN
    IF NEW.deleted_at IS NULL
       AND NEW.physical_collection_id IS NOT NULL
       AND NEW.tumbler ~ '^[0-9]+\.[0-9]+\.[0-9]+' THEN
        v_seg := split_part(NEW.tumbler, '.', 1) || '-' || split_part(NEW.tumbler, '.', 2);
        -- RDR-229 P3.5b: the registry row of the document's collection id, whatever name the document still carries.
        SELECT c.name, c.owner_id, c.content_type, c.embedding_model, c.model_version, c.lifecycle_state,
               (c.superseded_by_id IS NOT NULL)
          INTO v_name, v_cur, v_ct, v_em, v_mv, v_ls, v_sup
          FROM nexus.catalog_collections c
         WHERE c.tenant_id = NEW.tenant_id
           AND c.collection_id = NEW.physical_collection_id
           AND c.content_type IN ('code', 'docs', 'rdr');
        -- Cheap probes first: a settled repo collection (a tumbler-shaped owner) or one already
        -- owned by this very document's owner costs a primary-key read, never the aggregate over
        -- the collection's documents.
        IF FOUND
           AND v_cur IS DISTINCT FROM v_seg
           AND nexus.catalog_collection_owner_replaceable(NEW.tenant_id, v_cur) THEN
            v_new := nexus.catalog_collection_doc_owner(NEW.tenant_id, v_name);
            IF v_new IS NOT NULL AND v_new IS DISTINCT FROM v_cur THEN
                -- catalog-051-2: an unsuperseded, non-quarantine row must not land on a tuple another such row holds; the
                -- advisory lock serialises two writers onto one free tuple (see the BEFORE function above).
                IF v_ls <> 'quarantine' AND NOT v_sup THEN
                    PERFORM pg_advisory_xact_lock(nexus.collection_tuple_lock_key(
                        NEW.tenant_id, v_ct, v_new, v_em, v_mv));
                END IF;
                SELECT h.name INTO v_holder
                  FROM nexus.catalog_collections h
                 WHERE v_ls <> 'quarantine' AND NOT v_sup
                   AND h.tenant_id = NEW.tenant_id
                   AND h.content_type = v_ct
                   AND h.owner_id = v_new
                   AND h.embedding_model = v_em
                   AND h.model_version = v_mv
                   AND h.lifecycle_state <> 'quarantine' AND h.superseded_by_id IS NULL
                   AND h.collection_id <> NEW.physical_collection_id
                 ORDER BY h.name
                 LIMIT 1;
                IF FOUND THEN
                    RAISE NOTICE 'catalog-051: collection % keeps owner_id % (its documents name %, which collection % already holds for this content type, model and version)',
                        v_name, v_cur, v_new, v_holder;
                ELSE
                    RAISE NOTICE 'catalog-044: collection % owner_id % -> % (from its documents)',
                        v_name, v_cur, v_new;
                    UPDATE nexus.catalog_collections c
                       SET owner_id = v_new,
                         superseded_by_id = CASE WHEN c.superseded_by = '' THEN NULL
                             ELSE COALESCE(c.superseded_by_id,
                                           (SELECT s.collection_id FROM nexus.catalog_collections s
                                             WHERE s.tenant_id = c.tenant_id AND s.name = c.superseded_by),
                                           c.collection_id) END
                     WHERE c.tenant_id = NEW.tenant_id
                       AND c.collection_id = NEW.physical_collection_id
                       AND c.content_type IN ('code', 'docs', 'rdr')
                       AND c.owner_id IS DISTINCT FROM v_new
                       -- Re-checked on the row being updated: under READ COMMITTED a concurrent
                       -- transaction may have committed a repo owner since the SELECT above, and
                       -- this predicate is re-evaluated against that new row version, so a curator
                       -- (or slug) derivation cannot overwrite it.
                       AND nexus.catalog_collection_owner_replaceable(c.tenant_id, c.owner_id);
                END IF;
            END IF;
        END IF;
    END IF;
    RETURN NULL;
END;
$fn$;

