CREATE OR REPLACE FUNCTION nexus.canary_query_ring_upsert(
    p_tenant      text,
    p_collections text[],
    p_models      text[],
    p_vectors     text[],
    p_digests     bytea[]
) RETURNS integer
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_n       integer := coalesce(cardinality(p_digests), 0);
    v_written integer := 0;
    v_vec     nexus.vector;
    v_dims    integer;
    v_cid     bigint;
    v_name    text;
    v_cids    bigint[]  := ARRAY[]::bigint[];
    v_ring    bigint;
    i         integer;
BEGIN
    IF coalesce(cardinality(p_collections), 0) <> v_n
       OR coalesce(cardinality(p_models), 0)  <> v_n
       OR coalesce(cardinality(p_vectors), 0) <> v_n THEN
        RAISE EXCEPTION 'canary_query_ring_upsert: the four arrays must have the same length'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    FOR i IN 1 .. v_n LOOP
        CONTINUE WHEN p_collections[i] IS NULL OR p_models[i] IS NULL
                      OR p_digests[i] IS NULL OR p_vectors[i] IS NULL;
        v_vec  := p_vectors[i]::nexus.vector;
        v_dims := nexus.vector_dims(v_vec);
        CONTINUE WHEN v_dims NOT IN (384, 768, 1024);
        -- the entry's collection id and its registry label, from the registry in this statement's transaction. A name that does not
        -- resolve under the caller's row-level security (a cross-tenant name, or one with no registry row, including a collection
        -- deleted since the entry was enqueued) raises SQLSTATE 23503, the code assign_from_chashes uses for the same refusal; the id
        -- CHECK would refuse a NULL id anyway, and a silent skip hid the defect (RDR-229 P3.1, linda's ruling). PciQueryRing's writer
        -- retries a failed batch entry by entry, so one such entry does not drop the others. RDR-229 P3.5b: the ring is read and
        -- trimmed by collection_id; the name column is written from the registry's label of that id, never read.
        SELECT cc.collection_id, cc.name INTO v_cid, v_name FROM nexus.catalog_collections cc
         WHERE cc.tenant_id = p_tenant AND cc.name = p_collections[i]
         ORDER BY (cc.superseded_by_id IS NULL) DESC, cc.collection_id
         LIMIT 1;
        IF v_cid IS NULL THEN
            RAISE EXCEPTION 'canary_query_ring_upsert: collection % is not registered for tenant % -- register it first via POST /v1/catalog/collections/upsert',
                p_collections[i], p_tenant
                USING ERRCODE = 'foreign_key_violation';
        END IF;
        BEGIN
            -- refresh added_at when the digest is already in this collection's ring (by id), else insert
            UPDATE nexus.canary_query_ring r
               SET added_at = clock_timestamp(), collection_id = v_cid
             WHERE r.tenant_id = p_tenant
               AND r.collection_id = v_cid
               AND r.vector_digest = p_digests[i];
            IF NOT FOUND THEN
                IF v_dims = 384 THEN
                    INSERT INTO nexus.canary_query_ring
                        (tenant_id, collection, collection_id, embedding_model, embedding_384, vector_digest, added_at)
                    VALUES (p_tenant, v_name, v_cid, p_models[i], v_vec, p_digests[i], clock_timestamp());
                ELSIF v_dims = 768 THEN
                    INSERT INTO nexus.canary_query_ring
                        (tenant_id, collection, collection_id, embedding_model, embedding_768, vector_digest, added_at)
                    VALUES (p_tenant, v_name, v_cid, p_models[i], v_vec, p_digests[i], clock_timestamp());
                ELSE
                    INSERT INTO nexus.canary_query_ring
                        (tenant_id, collection, collection_id, embedding_model, embedding_1024, vector_digest, added_at)
                    VALUES (p_tenant, v_name, v_cid, p_models[i], v_vec, p_digests[i], clock_timestamp());
                END IF;
            END IF;
            v_written := v_written + 1;
            v_cids    := v_cids || v_cid;
        EXCEPTION
            WHEN foreign_key_violation THEN
                -- S6: the collection (or its model) is gone since the entry was enqueued. Skip this entry only.
                NULL;
            WHEN unique_violation THEN
                -- a concurrent call inserted the same entry between the UPDATE and the INSERT: refresh it, as ON CONFLICT did.
                UPDATE nexus.canary_query_ring r
                   SET added_at = clock_timestamp(), collection_id = v_cid
                 WHERE r.tenant_id = p_tenant
                   AND r.collection_id = v_cid
                   AND r.vector_digest = p_digests[i];
                v_written := v_written + 1;
                v_cids    := v_cids || v_cid;
        END;
    END LOOP;

    -- Trim each ring this call wrote to, in a fixed order (two concurrent calls take the same row locks in the
    -- same order): keep the 32 newest by added_at (ties on the digest), and nothing older than 30 days.
    FOR v_ring IN SELECT u.r FROM unnest(v_cids) AS u(r) GROUP BY u.r ORDER BY u.r LOOP
        DELETE FROM nexus.canary_query_ring d
         WHERE d.tenant_id = p_tenant
           AND d.collection_id = v_ring
           AND (d.added_at < clock_timestamp() - interval '30 days'
                OR d.vector_digest NOT IN (
                       SELECT k.vector_digest
                         FROM nexus.canary_query_ring k
                        WHERE k.tenant_id = p_tenant
                          AND k.collection_id = v_ring
                        ORDER BY k.added_at DESC, k.vector_digest
                        LIMIT 32));
    END LOOP;

    RETURN v_written;
END;
$fn$;

