        v_dims := nexus.vector_dims(v_vec);
        CONTINUE WHEN v_dims NOT IN (384, 768, 1024);
        -- the entry's collection id, from the registry in this statement's transaction. A name that does not resolve under the
        -- caller's row-level security (a cross-tenant name, or one with no registry row, including a collection deleted since the
        -- entry was enqueued) raises SQLSTATE 23503, the code assign_from_chashes uses for the same refusal; the id CHECK would
        -- refuse a NULL id anyway, and a silent skip hid the defect (RDR-229 P3.1, linda's ruling). PciQueryRing's writer retries a
        -- failed batch entry by entry, so one such entry does not drop the others.
        SELECT cc.collection_id INTO v_cid FROM nexus.catalog_collections cc
         WHERE cc.tenant_id = p_tenant AND cc.name = p_collections[i];
        IF v_cid IS NULL THEN
            RAISE EXCEPTION 'canary_query_ring_upsert: collection % is not registered for tenant % -- register it first via POST /v1/catalog/collections/upsert',
