                USING ERRCODE = 'foreign_key_violation';
        END IF;
        BEGIN
            IF v_dims = 384 THEN
                INSERT INTO nexus.canary_query_ring
                    (tenant_id, collection, collection_id, embedding_model, embedding_384, vector_digest, added_at)
                VALUES (p_tenant, p_collections[i], v_cid, p_models[i], v_vec, p_digests[i], clock_timestamp())
                ON CONFLICT (tenant_id, collection, vector_digest)
